CREATE TABLE public.embed_clicks (id uuid NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, profile_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, link_id uuid NOT NULL REFERENCES public.links(id) ON DELETE CASCADE, layout text NOT NULL, theme text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()); GRANT SELECT ON public.embed_clicks TO authenticated; GRANT ALL ON public.embed_clicks TO service_role; ALTER TABLE public.embed_clicks ENABLE ROW LEVEL SECURITY; CREATE POLICY "Owners read their embed clicks" ON public.embed_clicks FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.profiles p WHERE p.id = embed_clicks.profile_id AND p.user_id = auth.uid())); CREATE INDEX embed_clicks_profile_created_idx ON public.embed_clicks (profile_id, created_at DESC);